(5153015, 748916, 81362, '<td valign="top">Hilarious capture of eyes rolling up toward heaven at the thought of having to pose for yet another photo by the DPC member in the family.</td>', 'Hilarious capture of eyes rolling up toward heaven at the thought of having to pose for yet another photo by the DPC member in the family.', '2008-12-27 07:42:56.000000', NULL, 1),
(5153016, 749138, 81362, '<td valign="top">Cute toes, and wonderful mix of textures and lines.</td>', 'Cute toes, and wonderful mix of textures and lines.', '2008-12-27 07:43:29.000000', NULL, 1),
(5153017, 749067, 81362, '<td valign="top">Shallow depth of filed gives a nice blur to the decorative lights. Black and white works well in demonstrating the non-festive aspect of desire for money. The plant pot and the spangles on the Santa hat jumble up the image to my eye. Having only the spherical ornament and placing the cloth skirt over the edge of the pot might be useful simplifications.</td>', 'Shallow depth of filed gives a nice blur to the decorative lights. Black and white works well in demonstrating the non-festive aspect of desire for money. The plant pot and the spangles on the Santa hat jumble up the image to my eye. Having only the spherical ornament and placing the cloth skirt over the edge of the pot might be useful simplifications.', '2008-12-27 07:50:06.000000', NULL, 1),
(5153019, 749139, 81362, '<td valign="top">The image conveys a sense of looking into the past, perhaps at an art gallery. The title reveals the poignant context. Good art in a small package.</td>', 'The image conveys a sense of looking into the past, perhaps at an art gallery. The title reveals the poignant context. Good art in a small package.', '2008-12-27 07:52:39.000000', NULL, 1),
(5153020, 749108, 81362, '<td valign="top">But only if the store doesn''t go bankrupt, a risk in these troubled times. Diagonal ceiling lights well placed. Tilt of the rack and uneven lighting (as though from a small flash) detract - maybe a small diffuser might have helped.</td>', 'But only if the store doesn''t go bankrupt, a risk in these troubled times. Diagonal ceiling lights well placed. Tilt of the rack and uneven lighting (as though from a small flash) detract - maybe a small diffuser might have helped.', '2008-12-27 07:55:14.000000', NULL, 1),
(5153022, 748937, 81362, '<td valign="top">Nice placement of the setting and stone along the diagonal. Makes me want to see the facets of the stone sharper, but I know how hard that is to achieve.</td>', 'Nice placement of the setting and stone along the diagonal. Makes me want to see the facets of the stone sharper, but I know how hard that is to achieve.', '2008-12-27 07:57:22.000000', NULL, 1);
