INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5154885, 749069, 76335, '<td valign="top">Nicely lit and captured. Great tones in this one.</td>', 'Nicely lit and captured. Great tones in this one.', '2008-12-28 13:26:43.000000', NULL, 1),
