(5154890, 749111, 76335, '<td valign="top">Dream on. Nice lighting and focus here.</td>', 'Dream on. Nice lighting and focus here.', '2008-12-28 13:29:15.000000', NULL, 1),
(5154891, 749115, 76335, '<td valign="top">Dreamy, subtle. Nice job.</td>', 'Dreamy, subtle. Nice job.', '2008-12-28 13:29:44.000000', NULL, 1),
