(5154898, 749046, 76335, '<td valign="top">Is he/she behind the door? Perhaps a shadow of your expected guest would have added to the intrigue.</td>', 'Is he/she behind the door? Perhaps a shadow of your expected guest would have added to the intrigue.', '2008-12-28 13:32:38.000000', NULL, 1),
(5154899, 748898, 76335, '<td valign="top">Funny. Good vivid colors and energy.</td>', 'Funny. Good vivid colors and energy.', '2008-12-28 13:33:26.000000', NULL, 1),
(5154902, 749077, 76335, '<td valign="top">A bit harsh on the eyes as it''s a tad overexposed.</td>', 'A bit harsh on the eyes as it''s a tad overexposed.', '2008-12-28 13:35:13.000000', NULL, 1),
(5154903, 749138, 76335, '<td valign="top">Good use of grain. Nice conversion.</td>', 'Good use of grain. Nice conversion.', '2008-12-28 13:35:36.000000', NULL, 1),
(5154904, 748946, 76335, '<td valign="top">Been there! (Still am there.)</td>', 'Been there! (Still am there.)', '2008-12-28 13:36:07.000000', NULL, 1),
(5154908, 748961, 76335, '<td valign="top">Probably my favorite of the tree ornament shots thus far (and there have been lots in this and other challenges). Beautifully exposed and terrific sharpness and textures.</td>', 'Probably my favorite of the tree ornament shots thus far (and there have been lots in this and other challenges). Beautifully exposed and terrific sharpness and textures.', '2008-12-28 13:37:24.000000', NULL, 1),
(5154910, 749154, 76335, '<td valign="top">So I''ve heard.</td>', 'So I''ve heard.', '2008-12-28 13:38:03.000000', NULL, 1),
(5154911, 747955, 76335, '<td valign="top">Your title reveals what you wanted to capture or show us. So why would you you use selective desat to draw the eye away from her face and to her outfit?</td>', 'Your title reveals what you wanted to capture or show us. So why would you you use selective desat to draw the eye away from her face and to her outfit?', '2008-12-28 13:40:10.000000', NULL, 1),
