(5154922, 748645, 76335, '<td valign="top">Lacks in sharpness somewhat, but it''s brilliantly composed.</td>', 'Lacks in sharpness somewhat, but it''s brilliantly composed.', '2008-12-28 13:56:01.000000', NULL, 1),
(5154923, 749122, 76335, '<td valign="top">Beautiful colors here. Nice exposure and processing.</td>', 'Beautiful colors here. Nice exposure and processing.', '2008-12-28 13:56:28.000000', NULL, 1),
(5154924, 748903, 76335, '<td valign="top">Brilliantly conceived and well executed.</td>', 'Brilliantly conceived and well executed.', '2008-12-28 13:57:06.000000', NULL, 1),
(5154926, 748066, 102020, '<td valign="top">Great  How did you hold the camera steady?</td>', 'Great  How did you hold the camera steady?', '2008-12-28 14:01:27.000000', NULL, 1),
