(5155029, 749076, 78021, '<td valign="top">WOW...this one out-does the National Lampoons Christmas! :-S</td>', 'WOW...this one out-does the National Lampoons Christmas! :-S', '2008-12-28 15:04:03.000000', NULL, 1),
(5155030, 749046, 28742, '<td valign="top">...and all I want is your house! :P Love this concept and the angle. Great techincals as well. Good luck!</td>', '...and all I want is your house! :P Love this concept and the angle. Great techincals as well. Good luck!', '2008-12-28 15:04:05.000000', NULL, 1),
(5155032, 748994, 28742, '<td valign="top">A little hazy - maybe it''s morning eyes... *rubs eyes* - nope, still hazy. Maybe a touch of contrast adjustment would help.</td>', 'A little hazy - maybe it''s morning eyes... *rubs eyes* - nope, still hazy. Maybe a touch of contrast adjustment would help.', '2008-12-28 15:05:24.000000', NULL, 1),
