(5155035, 749138, 28742, '<td valign="top">You''ll regret that when she does. ;-) Love the bw, the concept, the DoF. Great job.</td>', 'You''ll regret that when she does. ;-) Love the bw, the concept, the DoF. Great job.', '2008-12-28 15:06:07.000000', NULL, 1),
(5155038, 748932, 28742, '<td valign="top">Very nice. Only nitpick is that I don''t think those style of borders work in this image. Good luck though! :)</td>', 'Very nice. Only nitpick is that I don''t think those style of borders work in this image. Good luck though! :)', '2008-12-28 15:07:27.000000', NULL, 1),
(5155040, 748066, 28742, '<td valign="top">OMG OMG! How did you know??? :P</td>', 'OMG OMG! How did you know??? :P', '2008-12-28 15:07:50.000000', NULL, 1),
(5155043, 748946, 28742, '<td valign="top">:) I think you''re doing fine with what you''ve got. ;-)</td>', ':) I think you''re doing fine with what you''ve got. ;-)', '2008-12-28 15:08:43.000000', NULL, 1),
(5155053, 749121, 28742, '<td valign="top">I like the desat, but the snow is a bit gray and the composition just doesn''t work for me. Maybe if you included the whole tree? Good job overall.</td>', 'I like the desat, but the snow is a bit gray and the composition just doesn''t work for me. Maybe if you included the whole tree? Good job overall.', '2008-12-28 15:11:50.000000', NULL, 1),
(5155056, 749066, 28742, '<td valign="top">Not a fan of the composition - everything being cut off. Maybe if you didn''t crop the sticks it would leave something in tact. Just my preference though. I like the dof.</td>', 'Not a fan of the composition - everything being cut off. Maybe if you didn''t crop the sticks it would leave something in tact. Just my preference though. I like the dof.', '2008-12-28 15:13:01.000000', NULL, 1),
(5155058, 749090, 28742, '<td valign="top">lighting''s a little flat and a tad yellow. Just needs some minor improvements in processing, IMO. Good luck.</td>', 'lighting''s a little flat and a tad yellow. Just needs some minor improvements in processing, IMO. Good luck.', '2008-12-28 15:15:09.000000', NULL, 1),
(5155060, 748858, 28742, '<td valign="top">Mmmmmmm... :)</td>', 'Mmmmmmm... :)', '2008-12-28 15:16:15.000000', NULL, 1),
