(5155074, 748101, 3306, '<td valign="top">Beautifully done. You have set the mood wonderfully. I like your technique. One of my favorites of this challenge. Good luck</td>', 'Beautifully done. You have set the mood wonderfully. I like your technique. One of my favorites of this challenge. Good luck', '2008-12-28 15:30:23.000000', NULL, 1),
